//! External witness/adversarial/knowledge calibration shapes.
//!
//! These types are intentionally data-only. Brain consumes them as an optional
//! L2/L1 signal without changing the JSON summary artifact generated by
//! `aegis-measure`.

use serde::{Deserialize, Serialize};
use serde_json::Value;

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct ExternalCalibrationSnapshot {
    pub schema_version: u8,
    #[serde(default)]
    pub source: String,
    #[serde(default)]
    pub generated_at_unix_ms: Option<u64>,
    #[serde(default)]
    pub freshness_half_life_secs: Option<u64>,
    #[serde(default)]
    pub witness: Vec<ExternalWitnessCalibration>,
    #[serde(default)]
    pub adversarial: Vec<ExternalAdversarialCalibration>,
    #[serde(default)]
    pub knowledge: Vec<ExternalKnowledgePrior>,
    #[serde(default)]
    pub verdict: ExternalCalibrationVerdict,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct ExternalWitnessCalibration {
    pub label: String,
    pub records: u64,
    pub combined_avg: f64,
    pub ja3_present_avg: f64,
    pub alpn_match_avg: f64,
    pub sni_structure_avg: f64,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct ExternalAdversarialCalibration {
    pub transport: String,
    pub records: u64,
    pub measured: u64,
    pub planned: u64,
    pub passed: u64,
    pub failed: u64,
    pub pass_rate: Option<f64>,
    pub threshold: Option<f64>,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct ExternalKnowledgePrior {
    pub target_class: String,
    pub region_id: Option<String>,
    pub score: f64,
    pub confidence: f64,
    pub hard_excluded: bool,
    #[serde(default)]
    pub fail_closed: bool,
    #[serde(default)]
    pub generated_at_unix_ms: Option<u64>,
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct ExternalCalibrationVerdict {
    pub status: String,
    pub acceptance_degraded: bool,
    #[serde(default)]
    pub reasons: Vec<String>,
}

impl ExternalCalibrationSnapshot {
    pub fn from_summary_value(value: &Value) -> Self {
        let schema_version = value
            .get("schema_version")
            .and_then(Value::as_u64)
            .unwrap_or(1) as u8;

        Self {
            schema_version,
            source: value
                .get("event")
                .and_then(Value::as_str)
                .unwrap_or("external_calibration_summary")
                .to_string(),
            generated_at_unix_ms: value.get("generated_at_unix_ms").and_then(Value::as_u64),
            freshness_half_life_secs: value
                .get("freshness_half_life_secs")
                .and_then(Value::as_u64),
            witness: parse_witness(value),
            adversarial: parse_adversarial(value),
            knowledge: Vec::new(),
            verdict: parse_verdict(value),
        }
    }

    pub fn has_measured_external_signal(&self) -> bool {
        !self.witness.is_empty()
            || self
                .adversarial
                .iter()
                .any(|transport| transport.measured > 0)
            || !self.knowledge.is_empty()
    }
}

fn parse_witness(value: &Value) -> Vec<ExternalWitnessCalibration> {
    value
        .get("witness")
        .and_then(|witness| witness.get("labels"))
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|item| ExternalWitnessCalibration {
            label: string_field(item, "label"),
            records: u64_field(item, "records"),
            combined_avg: f64_field(item, "combined_avg"),
            ja3_present_avg: f64_field(item, "ja3_present_avg"),
            alpn_match_avg: f64_field(item, "alpn_match_avg"),
            sni_structure_avg: f64_field(item, "sni_structure_avg"),
        })
        .collect()
}

fn parse_adversarial(value: &Value) -> Vec<ExternalAdversarialCalibration> {
    value
        .get("adversarial")
        .and_then(|adversarial| adversarial.get("transports"))
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|item| ExternalAdversarialCalibration {
            transport: string_field(item, "transport"),
            records: u64_field(item, "records"),
            measured: u64_field(item, "measured"),
            planned: u64_field(item, "planned"),
            passed: u64_field(item, "passed"),
            failed: u64_field(item, "failed"),
            pass_rate: item.get("pass_rate").and_then(Value::as_f64),
            threshold: item.get("threshold").and_then(Value::as_f64),
        })
        .collect()
}

fn parse_verdict(value: &Value) -> ExternalCalibrationVerdict {
    let verdict = value.get("verdict").unwrap_or(&Value::Null);
    ExternalCalibrationVerdict {
        status: verdict
            .get("status")
            .and_then(Value::as_str)
            .unwrap_or("UNKNOWN")
            .to_string(),
        acceptance_degraded: verdict
            .get("acceptance_degraded")
            .and_then(Value::as_bool)
            .unwrap_or(true),
        reasons: verdict
            .get("reasons")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
            .map(ToString::to_string)
            .collect(),
    }
}

fn string_field(value: &Value, field: &str) -> String {
    value
        .get(field)
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string()
}

fn u64_field(value: &Value, field: &str) -> u64 {
    value.get(field).and_then(Value::as_u64).unwrap_or_default()
}

fn f64_field(value: &Value, field: &str) -> f64 {
    value.get(field).and_then(Value::as_f64).unwrap_or_default()
}
